  selection: Selection,
): MarkdownClipboardPayload | null {
  const texts: string[] = [];
  const htmls: string[] = [];
  for (let index = 0; index < selection.rangeCount; index += 1) {
    const range = selection.getRangeAt(index);
    if (range.collapsed) continue;
    const container = document.createElement("div");
    container.appendChild(range.cloneContents());
    const ancestor = range.commonAncestorContainer;
    const ancestorElement =
      ancestor.nodeType === Node.ELEMENT_NODE ? (ancestor as Element) : ancestor.parentElement;
    // A selection inside one rendered formula copies its whole TeX source.
    const formula = ancestorElement
      ?.closest("[data-markdown-math]")
      ?.getAttribute("data-markdown-copy");
    if (formula) {
      texts.push(formula.trim());
      htmls.push(sanitizedHtmlFrom(container));
      continue;
    }
    // A selection within a diagram copies its complete Mermaid source.
    const diagramSource = ancestorElement
      ?.closest("[data-markdown-mermaid]")
      ?.getAttribute("data-markdown-copy");
    if (diagramSource) {
      texts.push(diagramSource.trim());
      htmls.push(sanitizedHtmlFrom(container));
      continue;
    }
    if (ancestorElement?.closest("pre")) {
      const text = range.toString();
      if (text) {
        texts.push(text);
        htmls.push(sanitizedHtmlFrom(container));
      }
      continue;
    }
    const text = serializeRenderedMarkdownFragment(container);
    if (!text) continue;
    texts.push(text);
    htmls.push(sanitizedHtmlFrom(container));
  }
  if (texts.length === 0) return null;
  return { text: texts.join("\n\n"), html: htmls.join("") };
}

